import {clamp,lerp,seedRandom} from './world.js';
export const machines=[{name:'HACHI 86',power:7.8,max:54,grip:1.03,spec:'FR · 230 PS · 均衡操控',color:[.89,.93,.92]},{name:'ROTARY R7',power:9.1,max:61,grip:.90,spec:'FR · 310 PS · 高速轉向',color:[1,.64,.15]},{name:'APEX GT-R',power:8.5,max:58,grip:1.2,spec:'AWD · 330 PS · 四驅抓地',color:[.26,.49,.9]}];
export class Race{
 constructor(track,car=0,mode='race',assist=true,autoGas=true){this.track=track;this.car=machines[car];this.carId=car;this.mode=mode;this.assist=assist;this.autoGas=autoGas;this.s=0;this.x=-1.6;this.speed=0;this.steer=0;this.lateral=0;this.angle=0;this.time=0;this.health=100;this.drift=0;this.drifting=false;this.maxSpeed=0;this.rpm=900;this.gear=1;this.hitCooldown=0;this.hit=0;this.done=false;this.place=8;this.flash=0;this.finishedAI=0;let rnd=seedRandom(123+track.id);this.opponents=mode==='race'?Array.from({length:7},(_,i)=>({s:12+i*7,x:(i%2?1:-1)*1.6,v:0,skill:.77+rnd()*.24,bias:(i%2?1:-1)*1.6,mesh:i%7,angle:0,seed:rnd()*6,finished:false})):[];this.place=this.opponents.length+1}
 resetOnRoad(){this.x=clamp(this.x,-2.5,2.5);this.lateral=0;this.angle=0;this.speed=Math.min(this.speed,16);this.health=Math.max(this.health,30)}
 update(dt,input){if(this.done)return;dt=Math.min(dt,.05);this.time+=dt;this.hit=0;this.hitCooldown=Math.max(0,this.hitCooldown-dt);this.flash=Math.max(0,this.flash-dt*2);const p=this.track.at(this.s),grip=this.track.grip*this.car.grip;let steer=(input.right?1:0)-(input.left?1:0),brake=input.brake?1:0,gas=(input.gas||this.autoGas)&&!brake?1:0,hand=input.drift&&this.speed>9;this.steer=lerp(this.steer,steer,1-Math.exp(-dt*8));const slope=(this.track.at(this.s+8).y-p.y)/8;const drag=.0023*this.speed*this.speed+.38+slope*9.81;this.speed+=((gas?this.car.power*(1-.28*(this.speed/this.car.max)**2):0)-drag-brake*19-(hand?3:0))*dt;const cap=this.car.max*(.65+.35*this.health/100);this.speed=clamp(this.speed,0,cap);let centrifugal=-p.curve*this.speed*this.speed*(this.assist?.10:.32);const target=this.steer*this.speed*(hand?.23:.18)*grip+centrifugal;this.lateral=lerp(this.lateral,target,1-Math.exp(-dt*(hand?2.4:grip*6)));this.x+=this.lateral*dt;this.angle=lerp(this.angle,clamp(this.lateral/Math.max(this.speed,5),-.3,.3)+(hand?this.steer*.11:0),1-Math.exp(-dt*5));this.s+=this.speed*dt;this.drifting=hand&&Math.abs(this.steer)>.25&&Math.abs(p.curve)>.0018;let gforce=Math.abs(p.curve)*this.speed*this.speed/9.81;if(gforce>grip*1.4)this.speed-=Math.min(6,(gforce-grip*1.4)*2)*dt;
 if(this.drifting)this.drift+=this.speed*dt*(1+Math.abs(p.curve)*100);if(Math.abs(this.x)>3.55)this.speed=Math.max(0,this.speed-dt*6);if(Math.abs(this.x)>4.02){this.x=clamp(this.x,-4.02,4.02);this.lateral*=-.25;if(this.hitCooldown===0&&this.speed>4){this.speed*=.66;this.health=Math.max(0,this.health-5);this.hitCooldown=.8;this.hit=1;this.flash=1}}
 for(let a of this.opponents){if(a.finished)continue;let pa=this.track.at(a.s+26),curve=Math.abs(pa.curve),safe=Math.sqrt((this.track.grip*1.15*9.81)/Math.max(curve,.001)),targetSpeed=clamp(safe,19,47)*a.skill;targetSpeed=Math.min(targetSpeed,this.car.max*.87);let lane=a.bias+Math.sin(a.s*.009+a.seed)*.35;for(let b of this.opponents){if(a===b)continue;let gap=b.s-a.s;if(gap>0&&gap<16&&Math.abs(a.x-b.x)<1.5){lane=-Math.sign(b.x||1)*1.7;if(gap<7)targetSpeed=Math.min(targetSpeed,Math.max(10,b.v-2))}}
 let gap=this.s-a.s;if(gap>0&&gap<18&&Math.abs(this.x-a.x)<1.7){lane=-Math.sign(this.x||1)*1.9;if(gap<6)targetSpeed=Math.min(targetSpeed,Math.max(8,this.speed-2))}a.x=lerp(a.x,clamp(lane,-2.8,2.8),1-Math.exp(-dt*1.2));a.v=lerp(a.v,targetSpeed,1-Math.exp(-dt*.37));a.s+=a.v*dt;if(a.s>=this.track.length){a.finished=true;this.finishedAI++}if(Math.abs(a.s-this.s)<3.7&&Math.abs(a.x-this.x)<1.6&&this.hitCooldown===0&&this.speed>3){this.speed*=.76;a.v*=.9;this.x+=Math.sign(this.x-a.x||1)*.36;this.health=Math.max(0,this.health-3);this.hitCooldown=.7;this.hit=2;this.flash=.6}}
 this.place=1+this.opponents.filter(a=>a.s>this.s||a.finished).length;this.maxSpeed=Math.max(this.maxSpeed,this.speed*3.6);this.gear=Math.min(5,1+Math.floor(this.speed/11));this.rpm=clamp(1000+(this.speed%11)/11*5600+(gas?600:0),900,7800);if(this.s>=this.track.length){this.s=this.track.length;this.done=true}}
}
